    agent_pos = observation.get('agent_position', (0, 0))
    height = observation.get('board_height', 0)
    width = observation.get('board_width', 0)
    opponents = observation.get('opponents', [])
    resources = observation.get('resources', [])
    territory = observation.get('territory', [])
    mode = observation.get('mode', '')

    ax, ay = agent_pos

    def is_valid(pos):
        x, y = pos
        return 0 <= x < width and 0 <= y < height

    # Gather positions of relevant entities
    opponent_positions = [tuple(op.get('position', ())) for op in opponents]
    resource_positions = [tuple(r.get('position', ())) for r in resources]
    territory_positions = [tuple(t.get('position', ())) for t in territory]

    # Helper to get movement deltas
    def get_move_towards(targets):
        dxs = [0, -1, 1]
        dys = [0, -1, 1]
        for dx in dxs:
            for dy in dys:
                new_x = ax + dx
                new_y = ay + dy
                new_pos = (new_x, new_y)
                if is_valid(new_pos):
                    # For pursuit: move closer if possible
                    for t in targets:
                        # move if reduces distance
                        dist_before = abs(ax - t[0]) + abs(ay - t[1])
                        dist_after = abs(new_x - t[0]) + abs(new_y - t[1])
                        if dist_after < dist_before:
                            return dx, dy
        # Default to stay in place if no closer move found
        return 0, 0

    def move_away_from(targets):
        # Move in direction increasing distance from nearest target
        min_dist = float('inf')
        nearest = None
        for t in targets:
            dist = abs(ax - t[0]) + abs(ay - t[1])
            if dist < min_dist:
                min_dist = dist
                nearest = t
        if nearest is None:
            return 0, 0
        dxs = [0, -1, 1]
        dys = [0, -1, 1]
        best_move = (0, 0)
        max_dist = min_dist
        for dx in dxs:
            for dy in dys:
                new_x = ax + dx
                new_y = ay + dy
                new_pos = (new_x, new_y)
                if is_valid(new_pos):
                    dist = abs(new_x - nearest[0]) + abs(new_y - nearest[1])
                    if dist > max_dist:
                        max_dist = dist
                        best_move = (dx, dy)
        return best_move

    def stay_put():
        return 0, 0

    # Strategy based on mode
    if mode == 'resource_collection':
        if resource_positions:
            return get_move_towards(resource_positions)
        else:
            return stay_put()

    elif mode == 'pursuit_evasion':
        if opponents:
            return move_away_from(opponent_positions)
        else:
            return stay_put()

    elif mode == 'territory_control':
        # Move towards nearest unclaimed territory (if any)
        unclaimed = []
        for t in territory_positions:
            # Assuming each piece of territory has an 'owner' field
            # Defensive: get owner, default to None
